// Parity of ImmutableConverter with the C++ oracle on the OSS data set.
//
// Fixtures (Tests/Fixtures/oracle/lattice/, generated by
// Tools/make_lattice_fixtures.sh): for every line of
// Tests/Fixtures/oracle/conversion_inputs.txt, NNNN.tsv is the C++
// converter/debug_util DumpNodes() of the lattice and segments.tsv holds the
// resulting segments with their top-5 candidates, converted with the options
// of converter/immutable_converter_main.cc.

import Foundation
import GenmaiBase
import Testing

@testable import GenmaiCore

private struct OracleQuery {
  var id: String
  var query: String
  var ok: Bool
  /// "S\tkey\tsize" and "C\t..." lines.
  var segmentLines: [String] = []
}

private func loadOracleSegments() throws -> [OracleQuery] {
  let url = ConverterTestPaths.oracleDir.appendingPathComponent("lattice/segments.tsv")
  let text = try String(contentsOf: url, encoding: .utf8)
  var result: [OracleQuery] = []
  for line in text.split(separator: "\n", omittingEmptySubsequences: true) {
    let fields = line.split(separator: "\t", omittingEmptySubsequences: false)
    if fields[0] == "#" {
      result.append(OracleQuery(id: String(fields[1]), query: String(fields[2]), ok: fields[3] == "1"))
    } else {
      result[result.count - 1].segmentLines.append(String(line))
    }
  }
  return result
}

/// Converts `query` like immutable_converter_main.cc.
private func convertForParity(_ converter: ImmutableConverter, _ query: String)
  -> (ok: Bool, lattice: Lattice, segments: Segments)
{
  var options = ConversionOptions()
  options.requestType = .conversion
  options.useActualConverterForRealtimeConversion = true
  options.createPartialCandidates = false
  let request = ConversionRequestBuilder().setOptions(options).setKey(query).build()
  let segments = Segments()
  let lattice = Lattice()
  segments.initForConvert(request.key())
  let ok = converter.convert(request.options(), segments, lattice)
  return (ok, lattice, segments)
}

private func segmentLines(_ segments: Segments, topN: Int = 5) -> [String] {
  var lines: [String] = []
  for segment in segments.conversionSegments {
    lines.append("S\t\(segment.key)\t\(segment.candidatesSize)")
    for i in 0..<min(segment.candidatesSize, topN) {
      let c = segment.candidate(i)
      lines.append(
        "C\t\(c.value)\t\(c.key)\t\(c.contentKey)\t\(c.contentValue)\t\(c.cost)\t\(c.wcost)\t"
          + "\(c.structureCost)\t\(c.lid)\t\(c.rid)\t\(c.attributes)")
    }
  }
  return lines
}

private func firstDifference(_ a: [Substring], _ b: [Substring]) -> String {
  for i in 0..<max(a.count, b.count) {
    let x = i < a.count ? String(a[i]) : "<none>"
    let y = i < b.count ? String(b[i]) : "<none>"
    if !x.bytesEqual(y) {
      return "line \(i + 1):\n  oracle: \(x)\n  swift:  \(y)"
    }
  }
  return "(no difference)"
}

@Suite("ImmutableConverter oracle parity")
struct ImmutableConverterParityTests {
  @Test func latticeAndSegmentsMatchOracle() throws {
    guard let modules = try TestModules.oss() else {
      print("SKIP: Data/genmai.data is missing (run Tools/build_oracle.sh)")
      return
    }
    let converter = modules.makeImmutableConverter()
    let oracle = try loadOracleSegments()
    #expect(oracle.count == 734)

    var latticeMismatches: [String] = []
    var segmentMismatches: [String] = []
    var bestPathMismatches: [String] = []
    var report: [String] = []
    for item in oracle {
      let (ok, lattice, segments) = convertForParity(converter, item.query)
      #expect(ok == item.ok, "\(item.id) \(item.query)")

      // Lattice dump.
      let url = ConverterTestPaths.oracleDir.appendingPathComponent("lattice/\(item.id).tsv")
      let expected = try String(contentsOf: url, encoding: .utf8)
      let actual = ok ? dumpNodes(lattice) : ""
      if !expected.bytesEqual(actual) {
        latticeMismatches.append(item.id)
        if latticeMismatches.count <= 5 {
          report.append(
            "lattice \(item.id) \(item.query): "
              + firstDifference(
                expected.split(separator: "\n", omittingEmptySubsequences: false),
                actual.split(separator: "\n", omittingEmptySubsequences: false)))
        }
      }

      // Segments and top candidates.
      let actualLines = segmentLines(segments)
      let expectedLines = item.segmentLines
      if !actualLines.elementsEqual(expectedLines, by: { $0.bytesEqual($1) }) {
        segmentMismatches.append(item.id)
        if segmentMismatches.count <= 5 {
          report.append(
            "segments \(item.id) \(item.query): "
              + firstDifference(
                expectedLines.map { Substring($0) }, actualLines.map { Substring($0) }))
        }
      }

      // Best path: segment keys and top values.
      func bestPath(_ lines: [String]) -> [String] {
        var out: [String] = []
        var expectTop = false
        for line in lines {
          let f = line.split(separator: "\t", omittingEmptySubsequences: false)
          if f[0] == "S" {
            out.append("key=\(f[1])")
            expectTop = true
          } else if expectTop {
            out.append("value=\(f[1])")
            expectTop = false
          }
        }
        return out
      }
      if !bestPath(actualLines).elementsEqual(bestPath(expectedLines), by: { $0.bytesEqual($1) }) {
        bestPathMismatches.append(item.id)
      }
    }
    print(
      "ImmutableConverter parity: \(oracle.count) inputs, lattice mismatches: "
        + "\(latticeMismatches.count), segment/top-5 mismatches: \(segmentMismatches.count), "
        + "best-path mismatches: \(bestPathMismatches.count)")
    for line in report { print(line) }
    #expect(latticeMismatches.isEmpty, "lattice mismatches: \(latticeMismatches)")
    #expect(segmentMismatches.isEmpty, "segment mismatches: \(segmentMismatches)")
    #expect(bestPathMismatches.isEmpty, "best path mismatches: \(bestPathMismatches)")
  }
}
